import{z as r,x as d,o as e,c as s,q as l,j as A,D as E,d as t,s as i,S as B,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"autotuning 实践","description":"","frontmatter":{"title":"autotuning 实践","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-autotuning.md","filePath":"llm/ak-autotuning.md","lastUpdated":1791063341000}'),p={name:"llm/ak-autotuning.md"};function u(m,a,D,c,C,_){const o=d("Mermaid");return e(),s("div",null,[a[2]||(a[2]=l('<h1 id="autotuning-实践" tabindex="-1">autotuning 实践 <a class="header-anchor" href="#autotuning-实践" aria-label="Permalink to &quot;autotuning 实践&quot;">​</a></h1><div class="epigraph"><p>调参表是一份合同：形状桶是条款，缓存键是签名；漏一条，运行时就会拿错配置还理直气壮。</p><footer>—— 据 Tillet et al., Triton, 2019；内核自动调优与 vLLM 实现口径整理</footer></div><p><a href="/llm/ak-benchmark-methodology">上一课</a>立了测量的规矩。本课把测量变成搜索：autotuning 实践。<a href="/llm/kernel-autotuning">内核自动调优</a>定过「tile 与占用率是离散搜索、按形状桶离线调、热路径查表」的原则；本课落到注意力内核的完整实践：搜什么、什么时候搜、缓存什么、拿错了怎么办。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注意力内核的配置空间不小：<code>BLOCK_M</code>、<code>BLOCK_N</code>、<code>num_warps</code>、<code>num_stages</code>、沿 KV 的切段数、量化开关，组合上百。每个形状的最优不同：解码与前填的最优配置常差数倍，第一单元预算表里的每一个自由度都是搜索维。麻烦在时机：在线逐形状 JIT 调优会把所有候选配置全跑一遍，首个撞到新形状的请求付出整个搜索的延迟——服务里不可接受；离线又搜不全：部署形状永远比基准网格多。缺口是一份「离线尽量搜全、在线兜底不卡顿」的合同。</p><p><span class="marginnote">术语翻译：tile 就是把大矩阵切成小块、一小块一小块地算，<code>BLOCK_M</code>/<code>BLOCK_N</code> 决定每块多大；<code>num_warps</code> 是给一块派多少个线程束干活，<code>num_stages</code> 是流水线提前搬运几层数据。块太大装不进片上小仓库，太小则搬运太频繁——好值取决于矩阵形状，所以只能搜，不能拍脑袋定死。</span></p><h3 id="搜索目标跟着部署目标走" tabindex="-1">搜索目标跟着部署目标走 <a class="header-anchor" href="#搜索目标跟着部署目标走" aria-label="Permalink to &quot;搜索目标跟着部署目标走&quot;">​</a></h3><p>解码核按延迟调，前填核按吞吐调，同一个内核在两个目标下可以选出不同赢家。搜索时若目标与部署错位，表里的名次就是另一个问题的答案。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两级方案。第一级，离线：按上一课的协议扫形状网格乘配置空间，计时加数值验收，把每格的最优配置落成表。第二级，在线：缓存键取（形状桶、dtype、布局、因果与否、分页与否、\\(n_q\\) 桶——投机会把它从 1 变 \\(\\gamma+1\\)），命中查表，未命中回退到安全默认配置并异步补搜、回填表格。服务启动与图捕获阶段按预期形状预热，让真实请求永远不做第一个付学费的人。验收除时间外带占用率与 spill 计数：防止选出「快但贴着预算边缘」的脆弱配置——换个 batch 就溢出的赢家不值得要。</p><p><span class="marginnote">直觉类比：两级方案像餐厅备菜。开餐前（离线）按预估订单把常见菜配好；来了没备过的菜（缓存未命中），先按标准做法稳稳出一份（安全默认），同时让后厨研究最优做法写进菜谱（异步补搜回填）——客人从不需要站在灶台前等试验。</span></p>',11)),(e(),A(B,null,{default:E(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A6%BB%E7%BA%BF%EF%BC%9A%E5%BD%A2%E7%8A%B6%E7%BD%91%E6%A0%BC%20%C3%97%20%E9%85%8D%E7%BD%AE%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20B%5B%22%E6%8C%89%E5%9F%BA%E5%87%86%E5%8D%8F%E8%AE%AE%E8%AE%A1%E6%97%B6%E4%B8%8E%E9%AA%8C%E6%94%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%85%8D%E7%BD%AE%E8%A1%A8%EF%BC%9A%E9%94%AE%20%3D%20%E5%BD%A2%E7%8A%B6%E6%A1%B6%2Bdtype%2B%E5%B8%83%E5%B1%80%2B%E6%8E%A9%E7%A0%81%2Bn_q%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20F%5B%22%E6%8C%89%E8%A1%A8%E5%86%85%E9%85%8D%E7%BD%AE%E6%89%A7%E8%A1%8C%22%5D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5B%22%E5%AE%89%E5%85%A8%E9%BB%98%E8%AE%A4%20%2B%20%E5%BC%82%E6%AD%A5%E8%A1%A5%E6%90%9C%E5%9B%9E%E5%A1%AB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"为什么缓存键要这么长，逐条看漏一条的后果。形状漏了：相邻形状拿到别人的 tile，慢但不错。dtype 漏了：INT8 的配置喂给 FP8 内核，指令路径不同，轻则慢重则错。因果或树掩码漏了：掩码图不是键的一部分，动态稀疏内核可能拿到上一张图的块索引——读错块，输出错且静默。\\(n_q\\) 漏了：投机把解码形状变成短而宽，q=1 的最优 tile 对 \\(n_q=5\\) 常常劣化数倍。错法两型：全形状一份「通用最优」——各形状平均劣化、甜点之外全面失守；或者搜索时频率没锁、剖析器开着——上一课的每条规矩在搜索里都要重申一遍，因为搜索就是几百次基准。",-1)),(e(),A(B,null,{default:E(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20KEY%5B%22%E7%BC%93%E5%AD%98%E9%94%AE%22%5D%20--%3E%20K1%5B%22%E5%BD%A2%E7%8A%B6%E6%A1%B6%22%5D%0A%20%20KEY%20--%3E%20K2%5B%22dtype%22%5D%0A%20%20KEY%20--%3E%20K3%5B%22%E5%B8%83%E5%B1%80%20%2F%20%E5%9B%A0%E6%9E%9C%E6%8E%A9%E7%A0%81%22%5D%0A%20%20KEY%20--%3E%20K4%5B%22n_q%20%E6%A1%B6%22%5D%0A%20%20K1%20--%3E%7C%22%E6%BC%8F%E6%8E%89%22%7C%20F1%5B%22%E6%8B%BF%E5%88%B0%E9%82%BB%E5%B1%85%E7%9A%84%20tile%3A%20%E5%8F%AA%E6%98%AF%E5%8F%98%E6%85%A2%22%5D%0A%20%20K2%20--%3E%7C%22%E6%BC%8F%E6%8E%89%22%7C%20F2%5B%22INT8%20%E9%85%8D%E7%BD%AE%E5%96%82%20FP8%3A%20%E5%8F%AF%E8%83%BD%E7%AE%97%E9%94%99%22%5D%0A%20%20K3%20--%3E%7C%22%E6%BC%8F%E6%8E%89%22%7C%20F3%5B%22%E8%AF%BB%E9%94%99%E5%9D%97%3A%20%E9%9D%99%E9%BB%98%E9%94%99%E8%AF%AF%22%5D%0A%20%20K4%20--%3E%7C%22%E6%BC%8F%E6%8E%89%22%7C%20F4%5B%22%E6%8A%95%E6%9C%BA%E5%BD%A2%E7%8A%B6%E6%8B%BF%20q%3D1%20%E7%9A%84%20tile%3A%20%E5%8A%A3%E5%8C%96%E6%95%B0%E5%80%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">Triton 的 <code>@autotune</code> 常扫 8–32 组配置、每组 warmup 加重复计时；推理引擎在启动与 CUDA 图捕获前预热候选形状——生产里首 token 延迟尖刺，多半是某个形状漏进了「运行时现搜」的名单。</span></p><p>表的维护是机制的后半段。配置表随硬件换代作废：额度表变了（第 3 课）、原语变了（第 13 课），名次就变了，表要随版本重出。频率与功耗漂移让离线名次抖动，关键场景以在线实测复核；表格本身要有版本号与硬件指纹，回滚时整表回滚。autotune 修不了算法错误：掩码写错的内核，搜出来的只会是「稳定地错」——正确性验收在前，时间搜索在后，次序不能反。</p><p><span class="marginnote">为什么重要：配置表过期不会报错，只会悄悄变慢或溢出。所以换 GPU 型号、升内核版本时，要把配置表当成和模型权重一样的资产——重新生成、带版本号发布、能整表回滚，而不是拿旧表凑合着跑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课谈的是单内核、单设备的配置搜索；跨请求的调度级参数（批大小、配额）是服务课程的题。跨后端的配置表各出各的、验收口径统一，归到多后端一课。搜索开销本身（离线扫网格的机时）是工程预算的一部分：空间 sampled 而不是穷举，靠第一单元的账本先砍掉必输的候选——预算表不过关的配置不进搜索。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配置搜索分两级：离线按网格搜全、落表；在线查表、未命中走安全默认并异步补搜。</li><li>缓存键至少含形状桶、dtype、布局、掩码与 \\(n_q\\)；漏任何一条都可能静默拿错配置。</li><li>搜索目标与部署目标一致：解码按延迟、前填按吞吐，别用别人的考题选你的答案。</li><li>验收带占用率与 spill 计数，不选贴着预算边缘的脆弱赢家。</li><li>表随硬件与版本重出，带指纹与版本号；正确性验收先于时间搜索。</li><li>出处：Tillet et al., <em>Triton</em>, MAPL 2019；据 Triton autotune 与 vLLM 预热实现整理。</li></ul>',7))])}const g=r(p,[["render",u]]);export{F as __pageData,g as default};
